Derived from tablekeeper/spec/stage-2.md and the Architect's S2-RULINGS only.
"""
from __future__ import annotations

import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "suite-s1"))

import tk  # noqa: E402,F401
from tk import expect  # noqa: E402,F401

S1_URL = (os.environ.get("TK_S1_URL") or "").rstrip("/") or None   # ACCEPTED stage-1 image

LABELS = {"t_1": "Window", "t_2": "Booth", "t_3": "Terrace"}
PAIRS = [["t_1", "t_2"], ["t_2", "t_3"]]


def tables(caps=(2, 4, 6)):
    return [{"id": f"t_{i + 1}", "label": LABELS[f"t_{i + 1}"], "capacity": c}
            for i, c in enumerate(caps)]


def restaurant2(rid="r_anker", *, combinable=None, **kw):
    r = tk.restaurant(rid, **kw)
    if "tables" not in kw:
        r["tables"] = tables()
    r["combinable"] = PAIRS if combinable is None else combinable
    return r


def fixture2(**kw):
    if "restaurants" not in kw:
        kw["restaurants"] = [restaurant2()]
    return tk.fixture(**kw)


def book_set(api, rid, table_ids, starts_at_local, party_size=2, *, key=None, **extra):
    body = {"restaurant_id": rid, "table_ids": table_ids, "starts_at_local": starts_at_local,
            "party_size": party_size, **extra}
    return api.post("/reservations", body, key=tk.new_key() if key is None else key)


def book_set_ok(api, *a, **kw) -> dict:
    return expect(book_set(api, *a, **kw), 201).json()


def options(api, rid, date, party, hhmm):
    slots = expect(api.availability(rid, date, party), 200).json()["slots"]
    s = {x["starts_at_local"]: x for x in slots}[tk.local(date, hhmm)]
    return s


def assert_set_shape(r: dict, expected_ids: list[str]):
    assert r.get("table_ids") == expected_ids, (r.get("table_ids"), expected_ids)
    if len(expected_ids) == 1:
        assert r.get("table_id") == expected_ids[0], r
    else:
        assert "table_id" not in r, f"table_id must be omitted for a {len(expected_ids)}-set: {r}"


def members(r):
    if "table_ids" in r:
        return set(r["table_ids"])
    return {r["table_id"]}


def member_overlaps(reservations):
    """Confirmed reservations sharing ANY table member at overlapping times."""
    conf = [r for r in reservations if r.get("status") == "confirmed"]
    out = []
    for i, a in enumerate(conf):
        for b in conf[i + 1:]:
            if a["restaurant_id"] != b["restaurant_id"] or not (members(a) & members(b)):
                continue
            a0, a1 = tk.parse_ts(a["starts_at"]), tk.parse_ts(a["ends_at"])
            b0, b1 = tk.parse_ts(b["starts_at"]), tk.parse_ts(b["ends_at"])
            if a0 < b1 and b0 < a1:
                out.append((a["reference"], b["reference"]))
    return out
