{"args":{"content":""""Stage 3 black-box helpers (policies, revisions, history, series). Builds on suite-s2/tk2.py
and suite-s1/tk.py. Derived from tablekeeper/spec/stage-3.md and S3-RULINGS S3-R1..R11."""
from __future__ import annotations

import datetime as dt
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "suite-s2"))

import tk2  # noqa: E402
from tk2 import expect, tk  # noqa: E402,F401

S2_URL = (os.environ.get("TK_S2_URL") or "").rstrip("/") or None    # ACCEPTED stage-2 image
WD = tk.WEEKDAYS
CAPS0 = {"t_1": 2, "t_2": 4, "t_3": 6}
MANAGER = tk.CYD


def restaurant3(rid="r_anker", *, managers=("u_cyd",), **kw):
    r = tk2.restaurant2(rid, **kw)
    r["manager_user_ids"] = list(managers)
    return r


def fixture3(**kw):
    if "restaurants" not in kw:
        kw["restaurants"] = [restaurant3()]
    return tk.fixture(**kw)


def policy(effective_from, *, slot=30, duration=90, cutoff=120, hours=None, caps=None, **extra):
    return {"effective_from": effective_from, "slot_minutes": slot,
            "reservation_duration_minutes": duration, "cancellation_cutoff_minutes": cutoff,
            "opening_hours": tk.hours() if hours is None else hours,
            "capacities": dict(CAPS0 if caps is None else caps), **extra}


def publish(api, rid, pol, *, key=None):
    return api.post(f"/restaurants/{rid}/policies", pol, key=tk.new_key() if key is None else key)


def publish_ok(api, rid, pol, **kw):
    return expect(publish(api, rid, pol, **kw), 201).json()


def terms(pol_or_restaurant, version):
    """accepted_terms expected for a policy dict (or a fixture restaurant as policy 0)."""
    p = pol_or_restaurant
    caps = p["capacities"] if "capacities" in p else {t["id"]: t["capacity"] for t in p["tables"]}
    return {"policy_version": version, "slot_minutes": p["slot_minutes"],
            "reservation_duration_minutes": p["reservation_duration_minutes"],
            "cancellation_cutoff_minutes": p["cancellation_cutoff_minutes"],
            "opening_hours": p["opening_hours"], "capacities": caps}


def norm_terms(t):
    """Opening-hours order is not specified; compare as a weekday-sorted list."""
    if not isinstance(t, dict):
        return t
    out = dict(t)
    if isinstance(out.get("opening_hours"), list):
        out["opening_hours"] = sorted(out["opening_hours"],
                                      key=lambda h: (WD.index(h.get("weekday", "mon"))
                                                     if h.get("weekday") in WD else 9,
                                                     h.get("opens", "")))
    return out


