{"args":{"content":""""Scratch-only: render the Tablekeeper mark (terracotta disc, cream table) as PNG app icons.

Pure Python (zlib + struct), 4x4 supersampling. Usage: make_icons.py <out_dir>
"""
import struct
import sys
import zlib
from pathlib import Path

TERRACOTTA = (168, 70, 42)
CREAM = (251, 247, 240)
SS = 4  # samples per pixel per axis


def inside_glyph(x, y):
    """The table glyph in unit coordinates (0..1), matching icon.svg's 32-unit artwork."""
    def seg_h(y0, x0, x1, w):
        return x0 - w / 2 <= x <= x1 + w / 2 and abs(y - y0) <= w / 2

    def seg_v(x0, y0, y1, w):
        return y0 - w / 2 <= y <= y1 + w / 2 and abs(x - x0) <= w / 2

    w = 2 / 32
    return (seg_h(13.5 / 32, 9 / 32, 23 / 32, w) or seg_v(11 / 32, 13.5 / 32, 21.5 / 32, w)
            or seg_v(21 / 32, 13.5 / 32, 21.5 / 32, w) or seg_v(16 / 32, 9.5 / 32, 13.5 / 32, w))


def render(size, maskable):
    rows = []
    for py in range(size):
        row = bytearray([0])  # filter type 0
        for px in range(size):
            acc = [0, 0, 0, 0]
            for sy in range(SS):
                for sx in range(SS):
                    u = (px + (sx + 0.5) / SS) / size
                    v = (py + (sy + 0.5) / SS) / size
                    if maskable:
                        # Full-bleed background; the mark sits in the 80% safe zone.
                        gu, gv = (u - 0.1) / 0.8, (v - 0.1) / 0.8
                        colour = CREAM if 0 <= gu <= 1 and 0 <= gv <= 1 and inside_glyph(gu, gv) else TERRACOTTA
                        alpha = 255
                    else:
                        in_disc = (u - 0.5) ** 2 + (v - 0.5) ** 2 <= (15 / 32) ** 2
                        if not in_disc:
                            continue
                        colour = CREAM if inside_glyph(u, v) else TERRACOTTA
                        alpha = 255
                    acc[0] += colour[0] * alpha
                    acc[1] += colour[1] * alpha
                    acc[2] += colour[2] * alpha
                    acc[3] += alpha
            n = SS * SS
            a = acc[3] / n
            if acc[3]:
                row += bytes([round(acc[0] / acc[3]), round(acc[1] / acc[3]), round(acc[2] / acc[3]), round(a)])
            else:
                row += bytes([0, 0, 0, 0])
        rows.append(bytes(row))
    raw = b"".join(rows)

    def chunk(kind, data):
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr) + chunk(b"IDAT", zlib.compress(raw, 9)) + chunk(b"IEND", b"")


