{"args":{"content":""""Show MASKED context around secret-shaped matches in room.json. Never prints a secret value."""
import json
import re
import sys

path = sys.argv[1]
raw = open(path, encoding="utf-8").read()
MASK = [(re.compile(r"jrx_[0-9a-fA-F]{8,}"), lambda m: f"<LEASE len={len(m.group())}>"),
        (re.compile(r"\$argon2[^\s\"']*"), lambda m: f"<ARGON2 len={len(m.group())}>"),
        (re.compile(r"pbkdf2[^\s\"']*"), lambda m: f"<PBKDF2 len={len(m.group())}>"),
        (re.compile(r"[A-Za-z0-9_\-]{32,}"), lambda m: f"<LONG len={len(m.group())}>")]


def mask(s):
    for rx, fn in MASK:
        s = rx.sub(fn, s)
    return s


data = json.loads(raw)


def walk(o, trail):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from walk(v, trail + [k])
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from walk(v, trail + [i])
    elif isinstance(o, str):
        yield trail, o


# find the enclosing message for each match: report sender-ish fields by scanning parents
msgs = data if isinstance(data, list) else next((v for v in data.values() if isinstance(v, list)), [])
for pat in (r"jrx_[0-9a-fA-F]{16,}", r"\$argon2", r"pbkdf2"):
    rx = re.compile(pat)
    print(f"===== pattern {pat}")
    for idx, m in enumerate(msgs if isinstance(msgs, list) else []):
        blob = json.dumps(m, ensure_ascii=False)
        for hit in rx.finditer(blob):
            meta = {k: m.get(k) for k in ("id", "message_id", "sender", "sender_name", "type",
                                          "message_type", "created_at", "inserted_at")
                    if isinstance(m, dict) and k in m}
            if isinstance(m, dict):
                for k in ("sender", "author", "from"):
                    if isinstance(m.get(k), dict):
                        meta[k] = {kk: m[k].get(kk) for kk in ("handle", "name", "display_name", "id")}
            ctx = blob[max(0, hit.start() - 220): hit.end() + 160]
            print(f"-- msg#{idx} meta={json.dumps(meta)[:300]}")
            print("   ctx:", mask(ctx).replace("\\n", " ")[:500])
print("top-level type:", type(data).__name__, "keys:" if isinstance(data, dict) else "", list(data)[:10] if isinstance(data, dict) else len(data))
